  "settings.openchamber.opencodeCli.title": "OpenCode CLI",
  "settings.openchamber.tools.title": "Инструменты OpenChamber",
  "settings.openchamber.tools.field.agentControlTool": "Инструмент управления агентами",
  "settings.openchamber.tools.field.agentControlToolAria": "Включить инструмент управления агентами",
  "settings.openchamber.tools.field.agentControlToolInfo": "Позволяет агентам управлять вашей работой из чата: создавать сессии и worktree, передавать промпты другим агентам и управлять запланированными задачами. Добавляет краткое описание инструмента в каждую сессию. Применяется после перезапуска OpenCode.",
  "settings.openchamber.tools.field.agentWebTool": "Инструмент OpenChamber Web",
  "settings.openchamber.tools.field.agentWebToolAria": "Включить инструмент OpenChamber Web",
  "settings.openchamber.tools.field.agentWebToolInfo": "Позволяет агентам просматривать страницу в панели браузера OpenChamber и взаимодействовать с ней: открывать URL, читать страницу, нажимать, вводить текст, прокручивать и переключаться между мобильной и настольной вёрсткой. Добавляет краткое описание инструмента в каждую сессию. Применяется после перезапуска OpenCode.",
  "settings.openchamber.tools.field.agentMemoryTool": "Инструмент памяти агента",
  "settings.openchamber.tools.field.agentMemoryToolAria": "Инструмент памяти агента",
  "settings.openchamber.tools.field.agentMemoryToolInfo": "Позволяет агентам сохранять полученные знания между сессиями в двух хранилищах: что верно о вас и что верно о каждом проекте. Сессиям передаются сохранённые заголовки, чтобы агент мог прочитать запись, когда она уместна. Отключение убирает инструмент, вкладку «Память» и индекс сессий. Применяется после перезапуска OpenCode.",
  "settings.openchamber.opencodeCli.tooltipPrefix": "Необязательный абсолютный путь к",
