  "settings.magicPrompts.page.group.planImprove.description": "Скрытый промпт для отправки сохранённого плана в сценарий улучшения.",
  "settings.magicPrompts.page.group.planTodo.title": "Планирование задач",
  "settings.magicPrompts.page.group.planTodo.description": "Скрытый промпт для отправки задачи в новую сессию планирования.",
  "settings.magicPrompts.page.group.planImplement.title": "Реализация плана",
  "settings.magicPrompts.page.group.planImplement.description": "Скрытый промпт для отправки сохранённого плана в сценарий реализации.",
  "settings.magicPrompts.page.group.sessionSummary.title": "Итоги сессии",
  "settings.magicPrompts.page.group.sessionSummary.description": "Промпты для слэш-команды /summary: видимое сообщение пользователя + скрытые инструкции. Не разрушает данные — не сжимает историю сессии.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.title": "Ревью рабочей области",
  "settings.magicPrompts.page.group.sessionExplore.title": "Обзор кодовой базы",
  "settings.magicPrompts.page.group.sessionExplore.description": "Промпты для слэш-команды /explore: видимое сообщение пользователя + скрытые инструкции. Исследует репозиторий и даёт структурированную ориентацию — общую картину, основные модули, их связи и с чего начать — вместо перечисления файлов по одному.",
  "settings.magicPrompts.page.group.sessionWorkspaceReview.description": "Промпты для слэш-команды /workspace-review: видимое сообщение пользователя + скрытые инструкции. Проверяет дифф рабочей области на соответствие замыслу, корректность и достаточность, классифицируя находки по серьёзности.",
  "settings.magicPrompts.page.group.sessionFeaturePlan.title": "Планирование функции",
  "settings.magicPrompts.page.group.sessionFeaturePlan.description": "Промпты для слэш-команды /plan-feature: видимое сообщение пользователя + скрытые инструкции. Проводит управляемый диалог, который исследует код и задаёт уточняющие вопросы небольшими порциями, прежде чем составить план реализации.",
  "settings.magicPrompts.page.group.sessionCatchUp.title": "Наверстать",
  "settings.magicPrompts.page.group.sessionCatchUp.description": "Промпты для слэш-команды /catch-up: видимое сообщение пользователя + скрытые инструкции. Собирает контекст с учётом ветки — коммиты этой ветки, её PR и незакоммиченную работу вместе — чтобы понять, чем вы занимались, а затем даёт удобоваримое резюме и следующий шаг с фокусом на продукт.",
  "settings.magicPrompts.page.group.sessionDebug.title": "Отладка",
  "settings.magicPrompts.page.group.sessionDebug.description": "Промпты для слэш-команды /debug: видимое сообщение пользователя + скрытые инструкции. Проводит управляемое исследование первопричины — фиксирует симптом, выдвигает гипотезы, проверяет их по коду и подтверждает причину, прежде чем предложить исправление.",
  "settings.magicPrompts.page.group.sessionWeigh.title": "Взвесить варианты",
  "settings.magicPrompts.page.group.sessionWeigh.description": "Промпты для слэш-команды /weigh: видимое сообщение пользователя + скрытые инструкции. Исследует код, затем излагает 2–3 различных подхода с их плюсами и минусами и рекомендацией — без составления плана и написания кода.",
  "settings.magicPrompts.page.group.sessionFusion.title": "Fusion",
  "settings.magicPrompts.page.group.sessionFusion.description": "Промпты для объединения результатов нескольких запусков в один итоговый ответ: видимое сообщение пользователя + скрытые инструкции перед результатами источников.",
