  "chat.workStatus.telemetry.responseSpeed": "Ответ",
  "chat.workStatus.telemetry.responseSpeedDescription": "Как быстро пришёл итоговый текст. Без начального ожидания, рассуждений и прошлых вызовов инструментов. Оценка по отметкам времени текста, а не измерение скорости провайдером.",
  "chat.workStatus.telemetry.speed": "Весь ход",
  "chat.workStatus.telemetry.speedDescription": "Токены, сгенерированные на всех шагах, включая рассуждения, делённые на время без выполнения инструментов. Ожидание модели тоже учитывается, поэтому много коротких вызовов инструментов может снизить это число.",
  "chat.workStatus.telemetry.llmDuration": "Время модели",
  "chat.workStatus.telemetry.llmDurationDescription": "Время, потраченное на все шаги модели, включая ожидание ответов. Время выполнения инструментов исключено. Это не только время генерации текста.",
  "chat.workStatus.telemetry.toolDuration": "Инструменты",
  "chat.workStatus.telemetry.toolDurationDescription": "Время, потраченное на выполнение инструментов, включая неудачные вызовы. Инструменты, работающие одновременно, считаются один раз, а не суммируются.",
  "chat.workStatus.telemetry.ttft": "Средний TTFT",
  "chat.workStatus.telemetry.ttftDescription": "Среднее ожидание до начала первого текста или рассуждений на каждом шаге модели. Скрыто, если у какого-либо шага нет отметки начала, как часто бывает у шагов только с инструментами.",
  "chat.workStatus.telemetry.steps": "Шаги",
  "chat.workStatus.telemetry.stepsDescription": "Сколько раз модель вызывалась для этого промпта. Чтение результатов инструментов и решение, что делать дальше, обычно требует ещё одного шага.",
  "chat.workStatus.telemetry.tokens": "Токены",
  "chat.workStatus.telemetry.tokens.inOut": "{input} ↑ · {output} ↓",
  "chat.workStatus.telemetry.tokensDescription": "↑ Входные токены без кэшированных: {input}. ↓ Сгенерированные токены: {output} для текста и вызовов инструментов, плюс {reasoning} на рассуждения. Итоги охватывают все шаги этого промпта.",
  "chat.workStatus.telemetry.cacheHit": "Кэш",
  "chat.workStatus.telemetry.cacheHitDescription": "Доля входных токенов, переиспользованных из кэша промпта на всех шагах. Переиспользование контекста может снизить стоимость и ожидание, но это не оценка скорости.",
  "chat.workStatus.telemetry.cost": "Стоимость",
